function getSizesForPackedTexture(ans) {
  // capture width and height of each separate image
  const promises = ans.map(a => {
    return new Promise((resolve, reject) => {
      const img = new Image();
      const index = a.data.index;
      document.body.appendChild(img);
      img.onload = (e) => {
        const {offsetWidth, offsetHeight} = img;
        document.body.removeChild(img);
        resolve({width: offsetWidth, height: offsetHeight});
      };
      img.src = a.motif.color.url;
    });
  });

  // get median size for textures
  Promise.all(promises).then((values) => {
    const widths = [];
    const heights = [];
    values.forEach(({width, height}) => {
      widths.push(width);
      heights.push(height);
    });
    widths.sort((a, b) => a - b);
    heights.sort((a, b) => a - b);
  });

}

function createPackedTexture(ans) {
  const canvasAns = document.createElement('canvas');
  const ctx = canvasAns.getContext('2d');
  // median size
  const firstN = ans.length;
  const cols = Math.ceil(Math.sqrt(firstN));
  const rows = Math.ceil(firstN / cols);
  const size = 550;
  canvasAns.width = size * cols;
  canvasAns.height = size * rows;

  const promises = ans.slice(0, firstN).map((a, i) => {
    return new Promise((resolve, reject) => {
      const img = new Image();
      const index = a.data.index;
      document.body.appendChild(img);
      img.onload = (e) => {
        const x = (index % cols) * size;
        const y = Math.floor(index / cols) * size;
        ctx.drawImage(img, x, y, size, size);
        const {offsetWidth, offsetHeight} = img;
        document.body.removeChild(img);
        resolve({width: offsetWidth, height: offsetHeight});
      };
      img.src = a.motif.color.url;
    });
  });

  Promise.all(promises).then((values) => {
    canvasAns.toBlob((blob) => {
      const newImg = new Image();
      const url = URL.createObjectURL(blob);

      newImg.onload = () => {
        // no longer need to read the blob so it's revoked
        //URL.revokeObjectURL(url);
      };

      newImg.src = url;
      document.body.appendChild(newImg);
    }, 'image/jpeg', 0.90);
    //document.body.appendChild(canvasAns);
  });

}

